import os,json
from pathlib import Path
base=Path('/home/appontrack/public_html')
names=['mobile/updates','mobile/updates/native','saas/mobile/updates','saas/mobile/updates/native']
out={'uid':os.getuid(),'root':base.is_dir(),'dirs':{},'htaccess':(base/'.htaccess').is_file()}
for name in names:
 p=base/name
 item={'is_dir':p.is_dir(),'latest':(p/'latest.json').is_file()}
 if item['latest']:
  try:
   e=json.loads((p/'latest.json').read_text());m=json.loads(e.get('payload','{}'));item.update({'version':m.get('version_code'),'revision':m.get('revision'),'file':m.get('file','')[:90]})
  except Exception as ex:item['manifest_error']=type(ex).__name__
 out['dirs'][name]=item
print(json.dumps(out,separators=(',',':')))
